873	    UINT4               au4FirstPropId[] = SNX_PROP_MIBID_1;
874	    UINT4               au4SecondPropId[] = SNX_PROP_MIBID_2;
875	    UINT4               au4SnmpV2Id[] = SNX_SNMPV2_MIB_ID;
876	    INT4                i4RetVal = SNMP_FAILURE;
877	    tSNMP_OID_TYPE      MibID;
878	    UINT4               u4MinOidLen = SNMP_ZERO;
879	    UINT1               IsFirstPropMibReg = OSIX_FALSE;
880	    UINT1               IsSecondPropMibReg = OSIX_FALSE;
881	
882	    tSNMP_OID_TYPE     *pOid = NULL;
883	
884	    pOid = alloc_oid (MAX_OID_LENGTH);
