888	        return SNMP_FAILURE;
889	    }
890	    /*.The sub-agent does NOT support the capability to distribute 
891	     * a MIB across multiple sub-agents. So we register MIB II and
892	     * proprietory mib region. */
893	    MEMSET (&MibID, 0, sizeof (tSNMP_OID_TYPE));
894	    /* Since MIB tree is sorted lexographically, traverse it
895	     * find the root of the MIBs and then register */
896	    for (; pMibPtr != NULL; pMibPtr = pMibPtr->pNextMib)
897	    {
898	        /* No need to register MIBs under SNMPv2 Tree */
899	        if ((pMibPtr->pMibID->u4_Length >= SNX_SNMPV2_MIB_ID_LEN) &&
