914	             * (same as after a successful root register). */
915	            MibID.u4_Length = SNX_PROP_MIBID_1_LEN;
916	            MibID.pu4_OidList = au4FirstPropId;
917	            IsFirstPropMibReg = OSIX_TRUE;
