919	            continue;
920	        }
921	
922	        if ((IsSecondPropMibReg == OSIX_FALSE) &&
923	            (pMibPtr->pMibID->u4_Length >= SNX_PROP_MIBID_2_LEN) &&
924	            (MEMCMP (pMibPtr->pMibID->pu4_OidList, au4SecondPropId,
