939	            {
940	                SNMPTrace ("Registration of Proprietary OID-2 fails\n");
941	            }
942	            continue;
943	        }
944	        u4MinOidLen =
945	            MibID.u4_Length <
946	            pMibPtr->pMibID->u4_Length ? MibID.u4_Length : pMibPtr->pMibID->
947	            u4_Length;
948	
949	        if (u4MinOidLen != SNMP_ZERO)
950	        {
